@deco.set_separate_app_context(MONACO_APP_NAME)
def select_treatment_couch_position_done_button() -> None:
    """Locates the Treatment Couch Position dialog and clicks the Done button.
    """
    if CommonActions.find_object(MonacoCoreObjects.treatment_Couch_Position_Dialog) is not None:
        CommonActions.left_click_object(MonacoCoreObjects.treatment_Couch_Position_Done_Button)